        <div class='msg' id='lookup-msg'></div>

        <div class='panel' id='member-details' hidden>
          <h3>Member and plan details</h3>
          <p class='muted'>Pre-populated from the policy record. Correct anything that is out of date before you submit.</p>
          <div class='grid three'>
            <div class='field'><label for='member-name'>Member name</label><input type='text' id='member-name'></div>
            <div class='field'><label for='member-dob'>Date of birth</label><input type='text' id='member-dob'></div>
            <div class='field'><label for='member-plan'>Plan</label><input type='text' id='member-plan'></div>
            <div class='field'><label for='member-division'>Division</label><input type='text' id='member-division'></div>
            <div class='field'><label for='member-occupation'>Occupation</label><input type='text' id='member-occupation'></div>
            <div class='field'><label for='member-hire'>Hire date</label><input type='text' id='member-hire'></div>
