              <option>Illness — non-occupational</option>
              <option>Injury — non-occupational</option>
              <option>Surgery or hospitalization</option>
              <option>Mental health</option>
              <option>Pregnancy or parental — medical</option>
              <option>Workplace injury</option>
              <option>Other</option>
            </select>
          </div>
          <div class='field full'>
            <label for='claim-details'>Additional details <span class='hint'>(duties affected, expected return, accommodation offered)</span></label>
            <textarea id='claim-details' name='claim-details' placeholder='Describe the absence and anything intake should know to open the file.'></textarea>
          </div>
        </div>
      </div>
    </section>

    <section class='card'>
      <h2><span class='step'>3</span> Supporting documents</h2>
      <div class='card-body'>
        <div class='field'>
          <label for='documents'>Attach documents <span class='hint'>(PDF, JPG, PNG or DOCX — up to 10 MB each. Select several at once, or add more in a second selection.)</span></label>
