<footer><div><span>MapleSure Insurance — fictional demo application</span><span>SponsorConnect &middot; Group disability intake</span></div></footer>
<script>
(function () {
  var MEMBERS = {
    'GRP-778120|MBR-40917': {
      name: 'Dana R. Whitfield',
      dob: '1984-03-11',
      plan: 'Long-term disability — Plan B (66.7% of earnings)',
      division: 'Operations — Plant 2',
      occupation: 'Machine operator',
      hire: '2016-07-05'
    },
    'GRP-902355|MBR-11284': {
      name: 'Samuel O. Adeyemi',
      dob: '1979-11-27',
      plan: 'Short-term disability — Plan A (100% for 17 weeks)',
      division: 'Customer service — Central region',
      occupation: 'Claims service representative',
      hire: '2011-02-14'
    }
  };

  var ALLOWED = ['pdf', 'jpg', 'jpeg', 'png', 'docx'];
  var MAX_BYTES = 10 * 1024 * 1024;

  var form = document.getElementById('claim-form');
  var lookupBtn = document.getElementById('lookup-btn');
  var lookupMsg = document.getElementById('lookup-msg');
  var detailsPanel = document.getElementById('member-details');
  var docsInput = document.getElementById('documents');
  var fileList = document.getElementById('file-list');
  var noFiles = document.getElementById('no-files');
  var uploadMsg = document.getElementById('upload-msg');
  var formMsg = document.getElementById('form-msg');
  var confirmation = document.getElementById('confirmation');

  var attachments = [];
  var identified = null;

  function setMsg(el, text, kind) {
    el.textContent = text || '';
    el.className = text ? 'msg ' + kind : 'msg';
  }

  function setValue(id, value) {
    document.getElementById(id).value = value;
  }

  lookupBtn.addEventListener('click', function () {
    var policy = document.getElementById('policy-number').value.trim().toUpperCase();
    var member = document.getElementById('member-id').value.trim().toUpperCase();
    if (!policy || !member) {
      setMsg(lookupMsg, 'Enter both a policy number and a member ID to look up the member.', 'err');
      return;
    }
    var found = MEMBERS[policy + '|' + member];
    if (!found) {
      identified = null;
      detailsPanel.hidden = true;
      setMsg(lookupMsg, 'No member matches ' + policy + ' / ' + member + '. Check the numbers on the member card and try again.', 'err');
      return;
    }
    identified = found;
    setValue('member-name', found.name);
    setValue('member-dob', found.dob);
    setValue('member-plan', found.plan);
    setValue('member-division', found.division);
    setValue('member-occupation', found.occupation);
    setValue('member-hire', found.hire);
    detailsPanel.hidden = false;
    setMsg(lookupMsg, 'Member found: ' + found.name + '. Review the details below and correct anything that is out of date.', 'ok');
  });

  function extensionOf(name) {
    var i = name.lastIndexOf('.');
    return i < 0 ? '' : name.slice(i + 1).toLowerCase();
  }

  function readableSize(bytes) {
    if (bytes < 1024) { return bytes + ' B'; }
    if (bytes < 1024 * 1024) { return Math.round(bytes / 1024) + ' KB'; }
    return (bytes / 1024 / 1024).toFixed(1) + ' MB';
  }

  function renderFiles() {
    fileList.textContent = '';
    attachments.forEach(function (file, index) {
      var li = document.createElement('li');

      var icon = document.createElement('span');
      icon.className = 'doc-ico';
      icon.textContent = (extensionOf(file.name) || 'doc').slice(0, 4).toUpperCase();

      var name = document.createElement('span');
      name.textContent = file.name;

      var size = document.createElement('span');
      size.className = 'sz';
      size.textContent = readableSize(file.size);

      var remove = document.createElement('button');
      remove.type = 'button';
      remove.className = 'rm';
      remove.textContent = 'Remove';
      remove.addEventListener('click', function () {
        attachments.splice(index, 1);
        renderFiles();
        setMsg(uploadMsg, attachments.length + ' document(s) attached to this submission.', 'ok');
      });

      li.appendChild(icon);
      li.appendChild(name);
      li.appendChild(size);
      li.appendChild(remove);
      fileList.appendChild(li);
    });
    fileList.hidden = attachments.length === 0;
    noFiles.hidden = attachments.length > 0;
  }

  docsInput.addEventListener('change', function () {
    var rejected = [];
    Array.prototype.forEach.call(docsInput.files, function (file) {
      if (ALLOWED.indexOf(extensionOf(file.name)) === -1) {
        rejected.push(file.name + ' (file type not accepted)');
        return;
      }
      if (file.size > MAX_BYTES) {
        rejected.push(file.name + ' (' + readableSize(file.size) + ' — over the 10 MB limit)');
        return;
      }
      var duplicate = attachments.some(function (a) {
        return a.name === file.name && a.size === file.size;
      });
      if (!duplicate) { attachments.push(file); }
    });
    docsInput.value = '';
    renderFiles();
    if (rejected.length) {
      setMsg(uploadMsg, 'Not attached: ' + rejected.join('; ') + '. Nothing from a rejected file has been kept. Accepted types are PDF, JPG, PNG and DOCX, up to 10 MB each. ' + attachments.length + ' document(s) remain attached.', 'err');
    } else {
      setMsg(uploadMsg, attachments.length + ' document(s) attached to this submission.', 'ok');
    }
  });

  form.addEventListener('submit', function (event) {
    event.preventDefault();

    var natureField = document.getElementById('nature-of-absence');
    var lastDay = document.getElementById('last-day-worked').value;
    var firstAbsent = document.getElementById('first-day-absent').value;
    var nature = natureField.value;

    var problems = [];
    if (!identified) { problems.push('look up the member'); }
    if (!lastDay) { problems.push('enter the last day worked'); }
    if (!firstAbsent) { problems.push('enter the first day absent'); }
    if (!nature) { problems.push('choose the nature of the absence'); }
    if (!attachments.length) { problems.push('attach at least one supporting document'); }
    if (!document.getElementById('attestation').checked) { problems.push('confirm the attestation'); }

    if (problems.length) {
      setMsg(formMsg, 'Before submitting, please ' + problems.join(', ') + '.', 'err');
      return;
    }

    var now = new Date();
    var month = String(now.getMonth() + 1);
    if (month.length < 2) { month = '0' + month; }
    var sequence = String(Math.floor(1000 + Math.random() * 9000));
    var reference = 'MS-' + now.getFullYear() + '-' + month + '-' + sequence;

    var names = attachments.map(function (f) { return f.name; });

    document.getElementById('reference-number').textContent = reference;
    document.getElementById('conf-member').textContent =
      document.getElementById('member-name').value + ' (' + document.getElementById('member-id').value.trim().toUpperCase() + ')';
    document.getElementById('conf-policy').textContent =
      document.getElementById('policy-number').value.trim().toUpperCase() + ' — ' + document.getElementById('member-plan').value;
    document.getElementById('conf-absence').textContent =
      nature + ' — first day absent ' + firstAbsent + ', last day worked ' + lastDay;
    document.getElementById('conf-docs').textContent = names.length + ' file(s): ' + names.join(', ');
    document.getElementById('conf-submitted').textContent = now.toLocaleString();

    setMsg(formMsg, '', 'ok');
    form.hidden = true;
    document.getElementById('intro').hidden = true;
    confirmation.hidden = false;
    window.scrollTo({ top: 0, behavior: 'smooth' });
  });

  renderFiles();
}());
</script>
</body>
